CREATE TABLE IF NOT EXISTS economic_consensus_provenance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reconciliation_id uuid NOT NULL, profile_id uuid NOT NULL, component text NOT NULL, score numeric NOT NULL DEFAULT 0, source_count integer NOT NULL DEFAULT 0, verified_source_count integer NOT NULL DEFAULT 0, evidence_refs jsonb NOT NULL DEFAULT '[]'::jsonb, relationship_refs jsonb NOT NULL DEFAULT '[]'::jsonb, explanation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now())